import{_ as t,o as a,c as o,ak as n}from"./chunks/framework.sV-XtlWr.js";const g=JSON.parse('{"title":"Desktop app","description":"","frontmatter":{"title":"Desktop app","lang":"en-US"},"headers":[],"relativePath":"desktop.md","filePath":"desktop.md","lastUpdated":1787172951000}'),s={name:"desktop.md"};function i(r,e,l,h,d,p){return a(),o("div",null,[...e[0]||(e[0]=[n(`<h1 id="desktop-app" tabindex="-1">Desktop app <a class="header-anchor" href="#desktop-app" aria-label="Permalink to &quot;Desktop app&quot;">​</a></h1><p>The Piwi Dashboard desktop app runs the <strong>entire dashboard on your machine</strong> — no Docker, no <code>npx</code>, no server to set up. It bundles the same server that ships as the Docker image, wraps it in a native window, and keeps your data in a local folder. It&#39;s ideal for a single developer who runs Playwright locally and wants permanent history, flaky scoring, failure clustering, and locator healing without standing up a server.</p><blockquote><p>Everything binds to <code>127.0.0.1</code> — the app is local-only and nothing is exposed to the network.</p></blockquote><p>The window navigates like a browser without looking like one: <strong>back/forward buttons</strong> sit at the top of the sidebar, and the mouse side buttons and trackpad swipe gestures your OS uses for history work too.</p><h2 id="download" tabindex="-1">Download <a class="header-anchor" href="#download" aria-label="Permalink to &quot;Download&quot;">​</a></h2><p>Grab the installer for your OS from the <a href="https://github.com/PiwiTests/platform/releases/latest" target="_blank" rel="noreferrer">latest release</a>:</p><table tabindex="0"><thead><tr><th>OS</th><th>Installer</th></tr></thead><tbody><tr><td><strong>Windows</strong></td><td><code>.msi</code></td></tr><tr><td><strong>macOS</strong> (Apple silicon)</td><td><code>.dmg</code></td></tr></tbody></table><p>Linux is not packaged yet — use <a href="/deployment.html">Docker or <code>npx</code></a> there.</p><h3 id="unsigned-builds" tabindex="-1">Unsigned builds <a class="header-anchor" href="#unsigned-builds" aria-label="Permalink to &quot;Unsigned builds&quot;">​</a></h3><p>Until code-signing certificates are in place the installers are <strong>unsigned</strong>, so your OS shows a first-run warning:</p><ul><li><strong>macOS:</strong> right-click the app → <strong>Open</strong> → <strong>Open</strong> (once).</li><li><strong>Windows:</strong> SmartScreen → <strong>More info</strong> → <strong>Run anyway</strong>.</li></ul><h2 id="where-your-data-lives" tabindex="-1">Where your data lives <a class="header-anchor" href="#where-your-data-lives" aria-label="Permalink to &quot;Where your data lives&quot;">​</a></h2><p>Open <strong>Settings → Storage → Data location</strong> to see the exact paths, or use the tray menu&#39;s <strong>Open data folder</strong>. By default everything sits under the OS app-data directory:</p><table tabindex="0"><thead><tr><th>OS</th><th>Location</th></tr></thead><tbody><tr><td><strong>Windows</strong></td><td><code>%APPDATA%\\io.piwitests.dashboard\\.data</code></td></tr><tr><td><strong>macOS</strong></td><td><code>~/Library/Application Support/io.piwitests.dashboard/.data</code></td></tr></tbody></table><p>That folder holds <code>piwi.db</code> (SQLite) and <code>storage/</code> (reports, traces, attachments). Back it up by copying the folder while the app is closed.</p><h2 id="running-in-the-background" tabindex="-1">Running in the background <a class="header-anchor" href="#running-in-the-background" aria-label="Permalink to &quot;Running in the background&quot;">​</a></h2><p>By default, closing the window quits the app. From the tray icon you can enable:</p><ul><li><strong>Run in background</strong> — closing the window keeps the server running in the tray, so submitting more results is instant and reopening is immediate.</li><li><strong>Start on login</strong> — launch the app (hidden, into the tray) when you log in.</li></ul><p>While the window is hidden or unfocused, subscribed <a href="/notifications.html">notifications</a> (the bell on a project page) show as <strong>native OS notifications</strong>, and each one bumps an unread count on the dock icon (macOS/Linux) and in the tray tooltip. Focusing the window clears it.</p><h2 id="sending-results-to-it" tabindex="-1">Sending results to it <a class="header-anchor" href="#sending-results-to-it" aria-label="Permalink to &quot;Sending results to it&quot;">​</a></h2><p>While the app is running, the reporter finds it by itself — no URL and no token in your config:</p><div class="language-typescript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">typescript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;@piwitests/reporter&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, { projectName: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;my-project&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }]</span></span></code></pre></div><p>The app publishes its address and access token to <code>~/.piwi/desktop.json</code> (<code>%USERPROFILE%\\.piwi\\desktop.json</code> on Windows) while it runs, rewriting the file on each launch and deleting it on quit. The reporter reads it <strong>only</strong> when your config and environment set no <code>serverUrl</code> and no <code>apiKey</code>, so a project already pointed at a shared dashboard — or a CI job with <code>PIWI_API_KEY</code> set — is never redirected here. See <a href="/reporter.html#finding-the-desktop-app-automatically">Finding the desktop app automatically</a>.</p><h3 id="configuring-it-by-hand" tabindex="-1">Configuring it by hand <a class="header-anchor" href="#configuring-it-by-hand" aria-label="Permalink to &quot;Configuring it by hand&quot;">​</a></h3><p>Discovery needs the tests and the app to run as the same user on the same machine. When they don&#39;t — a container, a different account, or a config that already sets <code>serverUrl</code> — open <strong>Settings → Storage → Send results to this app</strong> to copy the token and a ready-made snippet:</p><div class="language-typescript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">typescript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;@piwitests/reporter&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  serverUrl: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;http://localhost:3000&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  projectName: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;my-project&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  apiKey: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;pd_…&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// from Settings → Storage (or the PIWI_API_KEY env var)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}]</span></span></code></pre></div><p>The token is a <strong>local secret</strong> — prefer the <code>PIWI_API_KEY</code> env var over committing it. The app uses port <strong>3000</strong> by default (falling back to another local port only if 3000 is already taken — the window&#39;s address bar shows the actual one).</p><blockquote><p><strong>Why a token?</strong> The server binds <code>127.0.0.1</code>, which blocks other machines — but loopback alone doesn&#39;t stop <em>other local processes</em> or <em>web pages open in your browser</em> from reaching it. The token means only the app itself and tools you&#39;ve handed it to (your reporter) can submit or read. Accepting results from <em>other machines</em> over the network is intentionally not supported in the desktop build — run the <a href="/deployment.html">Docker image</a> for a shared, always-on server.</p></blockquote><h2 id="projects-from-local-folders" tabindex="-1">Projects from local folders <a class="header-anchor" href="#projects-from-local-folders" aria-label="Permalink to &quot;Projects from local folders&quot;">​</a></h2><p>Runs create projects automatically, but the desktop app can also start from the code: <strong>Projects → New project → Choose folder…</strong> picks a checkout on this machine, detects the name it would report under (the <code>projectName</code> in its Playwright config, else the <code>package.json</code> name, else the folder name), and checks the setup — Playwright config present, Playwright installed, the <a href="/reporter.html">reporter</a> installed and wired into the config. Anything missing is a warning, not a blocker: create the project anyway and run <code>npx @piwitests/reporter init</code> in the folder when you&#39;re ready. The chosen folder is linked to the new project automatically.</p><p>The link itself is a per-machine setting, managed with the rest of the project settings: <strong>project page → Edit → Local folder</strong> shows the folder, the same setup checks, and the <strong>Change</strong>/<strong>Unlink</strong> actions. The project page shows the link&#39;s status — <code>ready</code>, <code>needs setup</code>, or <code>missing</code> when the folder is gone — and jumps there. The link never leaves this machine.</p><h2 id="running-tests-from-the-app" tabindex="-1">Running tests from the app <a class="header-anchor" href="#running-tests-from-the-app" aria-label="Permalink to &quot;Running tests from the app&quot;">​</a></h2><p>A failing run is one click from a local retry. On a run page (or a single execution page), <strong>Run locally</strong> re-runs the failed tests on this machine — immediately, with the options you used last time. The app executes the folder&#39;s <em>own</em> Playwright with the app&#39;s bundled Node — nothing extra to install — and the output streams into the <strong>Local runs</strong> tray in the corner of the window.</p><ul><li><strong>First use:</strong> a dialog asks you to link the Piwi project to its checkout — the folder that contains the tests. Link it any time under <a href="#projects-from-local-folders"><strong>Edit → Local folder</strong></a>. The link stays on this machine; it is never sent anywhere.</li><li><strong>The arrow next to the button</strong> holds everything else: run headless, headed, under the Playwright inspector or in UI mode; select tests by <code>file:line</code>, title or file; force trace recording; <code>--repeat-each</code> up to 1000× for flake reproduction. Whatever you pick becomes the new one-click default for that project. <strong>Run with options…</strong> opens the full dialog with the exact command preview.</li><li><strong>The button is also the run&#39;s status:</strong> it shows progress while tests run and the result when they finish; clicking it opens the tray. Runs keep going while you browse other pages — closing the tray or navigating never kills anything. Stopping is always explicit, from the tray; a toast reports the result when a run ends, an OS notification does when the window is in the background, and leaving the app while runs are active — closing the window, quitting from the tray, or restarting for an update — asks first.</li><li><strong>More places to run from:</strong> a test case&#39;s evolution page has <strong>Reproduce locally</strong> (matched by title, ×20 with a trace — the flake-hunting preset, without touching your saved defaults), and a failure cluster&#39;s test evidence has <strong>Run affected locally</strong> for every test in the cluster.</li><li><strong>Wrong folder?</strong> If none of the tests exist in the linked folder (usually a project linked to a different checkout), the button opens the dialog instead of spawning a run that would die with a module-resolution error — fix the link there, or run anyway if your Playwright config resolves specs elsewhere.</li></ul><p>Results flow back automatically: the run executes your project&#39;s regular Playwright config, so the Piwi reporter in it reports to this app through the <a href="#sending-results-to-it">discovery file</a>, exactly like a run started from your terminal. As soon as the reporter checks in, the run&#39;s tray entry links straight to the new run — <strong>Live in Piwi</strong> — and while anything is running a pill in the sidebar keeps the tray one click away from every page.</p><p>Two prerequisites, both usually already true for a project that reports to Piwi: the linked folder has <code>@playwright/test</code> installed (<code>node_modules</code> present — monorepos with a hoisted root install work too), and its Playwright config includes the Piwi reporter. Both show in the <a href="#projects-from-local-folders"><strong>Local folder</strong> checks</a>, and the run dialog warns up front when no Playwright installation is found.</p><p>The linked folder also completes <a href="/ide-integration.html">Open in IDE</a>: when no workspace root is configured there, source links resolve against the linked folder automatically.</p><h2 id="importing-local-files" tabindex="-1">Importing local files <a class="header-anchor" href="#importing-local-files" aria-label="Permalink to &quot;Importing local files&quot;">​</a></h2><p>Drop a Playwright <strong>blob report</strong> or <strong>trace</strong> (<code>.zip</code>) anywhere on the app window and an import dialog opens: pick the project, and each archive is imported straight from its path on disk — nothing is uploaded anywhere. Several traces dropped together can be gathered into a single run.</p><p>The same dialog opens when the OS hands files to the app: <strong>Open with → Piwi Dashboard</strong> in your file manager, dropping archives on the dock icon (macOS), or launching the app with file arguments. The app registers as an <em>optional</em> opener for <code>.zip</code> files — it never takes over your system&#39;s default archive handler.</p><p>Semantics match the <a href="/importing-runs.html">import page</a>: idempotent by content hash, and imports never trigger notifications, AI diagnosis or regression signals.</p><h2 id="connecting-ai-assistants" tabindex="-1">Connecting AI assistants <a class="header-anchor" href="#connecting-ai-assistants" aria-label="Permalink to &quot;Connecting AI assistants&quot;">​</a></h2><p>The app exposes the same <a href="/mcp.html">MCP server</a> as every Piwi deployment — and on this machine it can also do the wiring. The <strong>MCP server</strong> page detects installed clients — Claude Code, Claude Desktop, Cursor, VS Code, Windsurf and Gemini CLI — and connects each with one click:</p><ul><li>The <code>piwi</code> entry is written into the client&#39;s <strong>own config file</strong>, with the app&#39;s URL and access token filled in; a backup copy is kept next to the file, and only that one entry is ever added, updated or removed.</li><li>A config that is not plain JSON (comments, trailing commas) is never rewritten — the page says so and shows the copy-paste snippet instead.</li><li>Written entries embed this app&#39;s address, which can change when port 3000 is taken — on every launch the app checks the clients it configured and rewrites any entry that drifted.</li><li><strong>Claude Desktop</strong> is wired differently, because its config file accepts only servers started as a local command — a URL entry there is reported as invalid and ignored. It is pointed at this app&#39;s own built-in bridge instead (<code>piwi-desktop mcp-stdio</code>), which speaks MCP over stdin/stdout and forwards to the local endpoint. Nothing to install, no Node, and no token written into Claude&#39;s config: the bridge looks the address up when it runs, so that entry never drifts. The app has to be <strong>running</strong> for Claude Desktop to reach it — keep <em>Run in background</em> (or <em>Start on login</em>) on if you want it always available.</li></ul><p>Restart the client after connecting; most MCP clients read their config at startup.</p><h2 id="updates" tabindex="-1">Updates <a class="header-anchor" href="#updates" aria-label="Permalink to &quot;Updates&quot;">​</a></h2><p><strong>Settings → About → Updates</strong> checks GitHub releases for a newer version, downloads it in the background, and applies it when you restart the app.</p><p>Update support exists only in releases built with the project&#39;s update signing key — the app verifies every download against the matching public key before installing anything. A build without that key (a dev build, or a release made before the key existed) says so on the card; update it by downloading the <a href="https://github.com/PiwiTests/platform/releases/latest" target="_blank" rel="noreferrer">latest release</a> installer, which keeps your data (the data folder lives outside the app).</p><h2 id="building-from-source" tabindex="-1">Building from source <a class="header-anchor" href="#building-from-source" aria-label="Permalink to &quot;Building from source&quot;">​</a></h2><p>See <a href="https://github.com/PiwiTests/platform/blob/main/apps/desktop/README.md" target="_blank" rel="noreferrer"><code>apps/desktop/README.md</code></a> for the local build steps (Node 24+, the Rust toolchain, and the Tauri system dependencies).</p>`,50)])])}const u=t(s,[["render",i]]);export{g as __pageData,u as default};
